// Explanations and conceptual links verified against src/, November 3, 2026.
window.ATLAS = {
  lanes: [
    {name:'CONTROL / START THE WORLD', files:['main','sandbox_view','yard']},
    {name:'AUTHORING & ACTORS / GIVE IT SOMETHING TO DO', files:['editor_view','editor','player','bombs']},
    {name:'SIMULATION / DECIDE WHAT BREAKS', files:['blast_query','destruction','physics']},
    {name:'FOUNDATIONS / DEFINE WHAT EXISTS', files:['model','geometry']},
    {name:'PRESENTATION / TURN STATE INTO PIXELS', files:['state','render_cache','debug_view']}
  ],
  files: {
    main:{lines:28,role:'Entry point',tag:'The front door.',description:'Creates the output directory, interprets command-line flags, and chooses which mode to run. With no flags, it opens the playable sandbox.',steps:['Prepare the output/ directory.','Dispatch smoke, soak, fixture, or help modes when requested.','Call run_sandbox() for normal play.'],functions:['main'],related:['sandbox_view'],snippet:'main'},
    sandbox_view:{lines:309,role:'Window & frame loop',tag:'The conductor you can see.',description:'Owns the raylib window, frame loop, HUD, settings panel, and inspection controls. It turns device input into game actions and draws the world every frame.',steps:['Read keyboard and mouse input, then ask yard.odin to route it.','Advance the simulation and interpolate poses between fixed ticks.','Draw the world, aim indicator, and raygui interface.'],functions:['run_sandbox','sandbox_read_input','sandbox_draw_world'],related:['main','yard','editor_view','state','debug_view'],snippet:'sandbox_read_input'},
    yard:{lines:202,role:'Game orchestration',tag:'Where everything meets.',description:'Defines Sandbox, the container for the scene, editor, player, bombs, settings, and previous poses. It coordinates resets, input rules, blasts, and the fixed simulation clock.',steps:['Rebuild authored objects and destructible ground on reset.','Route input around menus, editing, and blocked buttons.','At 60 fixed ticks per second: update actors, step physics, process bombs, and clean up fallen debris.'],functions:['sandbox_reset','sandbox_tick','sandbox_advance','sandbox_explode'],related:['sandbox_view','editor','player','bombs','destruction','physics','model'],snippet:'sandbox_tick'},
    editor_view:{lines:51,role:'Drawing interaction',tag:'Your mouse becomes a blueprint.',description:'Converts authored rectangles into screen previews and translates mouse gestures into editor operations. It supplies the material colors used by the interface and scene rendering.',steps:['Draw the existing rectangles, drag preview, and placement guides.','Start and finish a left-button drag in world coordinates.','Send placement and right-click removal to editor.odin, respecting UI and menu input.'],functions:['sandbox_draw_editor','sandbox_editor_input','editor_color'],related:['sandbox_view','editor','debug_view'],snippet:'editor_color'},
    editor:{lines:107,role:'Authored layouts',tag:'The undamaged original.',description:'Keeps a list of rectangles separate from the damaged simulation. Its material palette defines Wood, Glass, Rubber, and Stone; Test and Reset build a deterministic world from the same design.',steps:['Validate bounds, minimum size, overlaps, and the player spawn area.','Store each accepted rectangle with a stable authoring identity.','Build logical regions and bonds; pre-split rigid materials and fit Rubber to a flexible cell grid.'],functions:['editor_place','sandbox_toggle_editor','editor_build_rectangles'],related:['editor_view','yard','model','destruction'],snippet:'sandbox_toggle_editor'},
    player:{lines:94,role:'Movement & support',tag:'A small actor in a breakable world.',description:'Creates the capsule-shaped Box2D player and manages movement, grounded support, jumping, and respawning. It acts in the same physics world as the debris.',steps:['Inspect contact support to decide whether the player is grounded.','Before each step, apply movement and buffered or coyote-time jumps.','After the step, refresh support and respawn if the player falls out of bounds.'],functions:['player_create','player_before_step','player_after_step'],related:['yard','physics'],snippet:'player_after_step'},
    bombs:{lines:113,role:'Falling bombs',tag:'Another route to the same explosion.',description:'Manages the optional rain of physical bombs: independent drop randomness, spawning, landing contacts, fuses, and visual burst records. Bomb explosions reuse the manual blast path.',steps:['Spawn falling bodies on a randomized schedule before the solver runs.','After the solver, detect landings and count down their fuses.','Remove spent bodies, record bursts, and call sandbox_explode().'],functions:['bomb_rain_before_step','bomb_rain_after_step','bomb_has_landed'],related:['yard','physics','destruction','sandbox_view'],snippet:'bomb_rain_before_step'},
    blast_query:{lines:38,role:'Spatial candidates',tag:'Find the things worth asking.',description:'Narrows blast evaluation to nearby region IDs using the Box2D spatial index. It also includes newly staged children that do not yet have physics bodies.',steps:['Query an axis-aligned box around the blast; read stable IDs from shape user data.','Include pending regions, filter for live records, and sort IDs deterministically.','Collect and deduplicate incident connections for those regions. Without active physics, consider all live regions.'],functions:['blast_regions','blast_connections'],related:['destruction','physics','model'],snippet:'blast_connections'},
    destruction:{lines:439,role:'Fracture & blast rules',tag:'The heart of the breakage.',description:'Generates child polygons and decides how blasts and other failures change the structure. A blast is one structural event that can evaluate several generations before the surviving pieces move.',steps:['Refine outlines reached by the destructive core, then compare radial load with material strength.','Stage failed regions and bonds; re-evaluate children against the same blast until no further failures remain.','Regroup pieces, commit the structure, synchronize physics, and apply impulses once to final survivors.'],functions:['generate_children','stage_failures','blast_pass','apply_failures'],related:['blast_query','model','geometry','physics','yard'],snippet:'blast_load'},
    physics:{lines:316,role:'Box2D bridge',tag:'Give the graph weight and motion.',description:'Maps logical pieces and regions to Box2D bodies, collision shapes, and joints. Rigid materials share a body per piece; flexible materials use region bodies joined by spring welds.',steps:['Synchronize changed topology and preserve motion when pieces split.','Step the Box2D world and copy body motion back to the logical scene.','Convert confirmed collision hit speeds into material loads, apply failures, and synchronize again.'],functions:['physics_sync_structure','physics_tick','calculate_physics_loads'],related:['model','geometry','destruction','blast_query','yard','player','bombs'],snippet:'physics_tick'},
    model:{lines:395,role:'Shared scene model',tag:'The vocabulary of the whole world.',description:'Defines Scene, Material, Subdivision, Connection, Piece, and Pose. A subdivision is a polygonal region; a connection is a bond; a piece groups connected regions.',steps:['Assign monotonic IDs and map them to packed storage rows.','Own outlines, memberships, incident links, and future generation seed contexts.','Rebuild connected groups after damage and reclaim dead records during structural commits.'],functions:['add_subdivision','rebuild_piece','commit_structure'],related:['yard','editor','destruction','physics','blast_query','geometry','state','render_cache','debug_view'],snippet:'new_scene'},
    geometry:{lines:192,role:'Polygon tools',tag:'The mathematics beneath the cracks.',description:'Supplies shared-boundary, hull, polygon-validity, and convex-decomposition operations. Logical fracture outlines stay distinct from the convex shapes needed by the collision engine.',steps:['Find common boundaries so child regions inherit the right surviving bonds.','Displace shared cut boundaries consistently on both sides while preserving valid outlines.','Compute convex hulls and decompose outlines into convex collision parts.'],functions:['shared_segments','displace_shared_boundaries','convex_decomposition'],related:['model','destruction','physics'],snippet:'shared_segments'},
    state:{lines:218,role:'Snapshots & interpolation',tag:'Remember the world. Smooth its motion.',description:'Validates and serializes the current simulation as JSON, restores snapshots, and interpolates poses for rendering. Snapshots describe existing geometry and motion; they do not save the authored editor layout.',steps:['Validate IDs, memberships, outlines, materials, and finite values.','Encode or decode snapshot data, excluding runtime Box2D handles.','Blend previous and current poses, keeping rigid regions in a shared frame between ticks.'],functions:['validate_scene','encode_snapshot','decode_snapshot','interpolate_region_pose'],related:['model','sandbox_view','debug_view'],snippet:'interpolate_pose'},
    render_cache:{lines:259,role:'Surface & seam caches',tag:'Make fragments look like a surface.',description:'Caches triangle indices, split boundaries, and seam neighbours so each frame can transform prepared geometry. Flexible surfaces can blend presentation vertices while simulation geometry stays intact.',steps:['Rebuild cached topology when the owning piece changes.','Transform rest vertices into interpolated render poses; optionally blend flexible surfaces.','Draw cached fills, fill-colored edge seals, and visible outline strokes.'],functions:['ensure_render_cache','render_outline','draw_cached_fill'],related:['model','geometry','debug_view','physics'],snippet:'stroke_style'},
    debug_view:{lines:152,role:'Scene drawing & picking',tag:'The renderer behind the name.',description:'Despite its name, this file supplies shared scene rendering for normal play as well as inspection. It converts between world and screen coordinates, picks regions and bonds, and draws fills and outlines.',steps:['Convert coordinate systems and build interpolated rigid-piece frames.','Use render caches to draw fills, seam seals, and outlines in separate passes.','Support picking, IDs, connection visualization, and runtime counts for inspection.'],functions:['draw_scene','pick_subdivision','render_piece_frames'],related:['sandbox_view','editor_view','render_cache','model','state'],snippet:'screen_point'}
  },
  journeys:{
    build:{label:'BUILD A WORLD',steps:[
      {file:'main',title:'Open the front door',copy:'Normal launch calls run_sandbox(), which opens the window and creates the editor sandbox.',focus:['main','sandbox_view']},
      {file:'editor_view',title:'Turn a drag into a rectangle',copy:'The view reads world-space mouse gestures. The editor validates and stores the rectangle, material, and authoring identity.',focus:['editor_view','editor']},
      {file:'editor',title:'Press Test: rebuild from the blueprint',copy:'Switching out of Edit triggers a reset. Stored rectangles become material-specific regions; Rubber gets a connected grid.',focus:['editor','yard','model','destruction']},
      {file:'yard',title:'Add the ground and start physics',copy:'The reset adds destructible Stone terrain, initializes the Box2D world, and creates the floor and player.',focus:['yard','physics','player','model']},
      {file:'sandbox_view',title:'The world is ready to play',copy:'The frame loop routes input, advances fixed ticks through the yard, and draws the current world.',focus:['sandbox_view','yard','debug_view']}
    ]},
    blast:{label:'FOLLOW A BLAST',steps:[
      {file:'sandbox_view',title:'01. A click enters the loop',copy:'The frame loop reads the mouse. Input routing checks menus and mode; sandbox_blast() rejects an aim point inside solid geometry.',focus:['sandbox_view','yard']},
      {file:'yard',title:'02. Make one Blast value',copy:'sandbox_explode() combines the world-space position with the configured radius and passes that event to blast_pass(). Falling bombs join this same route.',focus:['yard','bombs','destruction']},
      {file:'blast_query',title:'03. Find nearby regions and bonds',copy:'Spatial queries supply stable region IDs. Pending children are included even before bodies exist, so new fragments remain reachable.',focus:['blast_query','model','physics','destruction']},
      {file:'destruction',title:'04. Break, then ask the children again',copy:'Refine reach, compare load with strength, and stage failures. Newly generated regions and bonds face the same blast until no further failures remain.',focus:['destruction','blast_query','geometry','model']},
      {file:'model',title:'05. Rebuild the connected pieces',copy:'Surviving bonds determine ownership. Affected groups are rebuilt, undersized groups are removed, and the structural commit reclaims dead records.',focus:['model','destruction']},
      {file:'physics',title:'06. Give only the survivors a push',copy:'Synchronize the final bodies and joints, then apply the blast impulse to surviving regions. Rigid pieces can translate and spin.',focus:['physics','destruction','model']},
      {file:'debug_view',title:'07. Draw what remains',copy:'The frame loop interpolates poses. The renderer refreshes affected caches and draws the new geometry, seams, and outlines.',focus:['sandbox_view','state','render_cache','debug_view']}
    ]},
    frame:{label:'DRAW A FRAME',steps:[
      {file:'sandbox_view',title:'Read input once per rendered frame',copy:'raylib supplies keyboard and mouse state. The yard routes actions around the editor, HUD, and settings panel.',focus:['sandbox_view','yard','editor_view']},
      {file:'yard',title:'Catch up in fixed-size ticks',copy:'An accumulator advances the world at 1/60 second per tick. Editing and the settings panel pause simulation.',focus:['yard','player','bombs','physics']},
      {file:'physics',title:'Move bodies, then resolve impact damage',copy:'Box2D steps the world, motion is read back, and contact hit speeds become failure loads. The shared destruction path updates the structure.',focus:['physics','destruction','model']},
      {file:'state',title:'Blend between solved poses',copy:'The frame loop interpolates with the remaining accumulator fraction. Rigid regions use a shared frame to stay visually rigid.',focus:['state','sandbox_view','debug_view']},
      {file:'render_cache',title:'Transform prepared geometry',copy:'Cached triangles and seam neighbours are reused until topology changes. Optional surface blending changes only the presentation.',focus:['render_cache','model','debug_view']},
      {file:'debug_view',title:'Paint the scene, then the interface',copy:'Draw fills, edge seals, and outlines. The window loop adds player and bomb visuals, aim feedback, the HUD, and settings.',focus:['debug_view','sandbox_view','editor_view']}
    ]}
  }
};

// Exact source excerpts.
for (const [id, value] of Object.entries({"main": {"source": "main :: proc() {\n\tif err:=os.make_directory_all(\"output\"); err!=nil {\n\t\tfmt.eprintln(\"Could not create output directory:\",err)\n\t\tos.exit(1)\n\t}\n\tfor arg,i in os.args[1:] {\n\t\tif arg==\"--soak\" {\n\t\t\tminutes:=20\n\t\t\tif i+2<len(os.args) { n,ok:=strconv.parse_int(os.args[i+2]); if !ok || n<1 { fmt.eprintln(\"--soak expects positive whole minutes\"); os.exit(1) }; minutes=n }\n\t\t\trun_soak(minutes); return\n\t\t}\n\t\tif arg==\"--soak-fixture\" {\n\t\t\tprefix:=string(\"output/soak-fixture\"); if i+2<len(os.args) { prefix=os.args[i+2] }; run_soak_fixtures(prefix); return\n\t\t}\n\t\tif arg==\"--smoke-msaa\" { run_sandbox(true,false,true); return }\n\t\tif arg==\"--smoke\" { run_sandbox(true); return }\n\t\tif arg==\"--smoke-input\" { run_sandbox(true,true); return }\n\t\tif arg==\"--help\" { fmt.println(\"odin run src -out:build/BOM.exe -- [--soak [minutes] | --soak-fixture [output-prefix] | --smoke-msaa | --smoke | --smoke-input | --help]\"); return }\n// ? excerpt continues in source", "sourceLine": 7}, "sandbox_view": {"source": "sandbox_read_input :: proc() -> Sandbox_Input {\n\tmove:=f32(0)\n\tif rl.IsKeyDown(.A) || rl.IsKeyDown(.LEFT) { move-=1 }\n\tif rl.IsKeyDown(.D) || rl.IsKeyDown(.RIGHT) { move+=1 }\n\treturn Sandbox_Input{move=move,jump_pressed=rl.IsKeyPressed(.SPACE),jump_down=rl.IsKeyDown(.SPACE),blast_pressed=rl.IsMouseButtonPressed(.LEFT),blast_down=rl.IsMouseButtonDown(.LEFT),menu_pressed=rl.IsKeyPressed(.TAB) || rl.IsKeyPressed(.ESCAPE),reset_pressed=rl.IsKeyPressed(.R),inspection_pressed=rl.IsKeyPressed(.F3),edit_pressed=rl.IsKeyPressed(.ENTER),wheel=rl.GetMouseWheelMove()}\n}", "sourceLine": 221}, "yard": {"source": "sandbox_tick :: proc(game: ^Sandbox,move: f32,jump: bool,dt: f32 = 1.0/60.0) {\n\tclear(&game.previous)\n\tfor sub in game.scene.subdivisions { if sub.live { game.previous[sub.id]=sub.pose } }\n\tgame.previous_player=from_b2(b2.Body_GetPosition(game.player.body))\n\tbomb_rain_before_step(game,dt)\n\tplayer_before_step(&game.player,move,jump,dt)\n\tphysics_tick(&game.scene,dt)\n\tbomb_rain_after_step(game,dt)\n\tsandbox_remove_out_of_bounds(game)\n\tif player_after_step(&game.player) {\n\t\tgame.previous_player=PLAYER_SPAWN\n\t\tsandbox_notice(game,\"Back at spawn\")\n\t}\n}\n// This is yard cleanup, not an impact or another generation of damage.", "sourceLine": 152}, "editor_view": {"source": "editor_color :: proc(name: string) -> rl.Color {\n\tswitch name {\n\tcase \"wood\": return {180,136,82,255}\n\tcase \"glass\": return {106,191,215,195}\n\tcase \"rubber\": return {162,112,184,255}\n\t}\n\treturn {131,145,152,255}\n}", "sourceLine": 5}, "editor": {"source": "sandbox_toggle_editor :: proc(game: ^Sandbox) {\n\tif game.panel_open { return }\n\tgame.editor.editing=!game.editor.editing\n\tgame.editor.dragging=false\n\tsandbox_reset(game)\n\tif game.editor.editing { sandbox_notice(game,\"Edit: undamaged layout restored\") }\n\telse { sandbox_notice(game,\"Test: R restores this layout and seed\") }\n}", "sourceLine": 61}, "player": {"source": "player_after_step :: proc(player: ^Player) -> bool {\n\tposition:=from_b2(b2.Body_GetPosition(player.body))\n\tif position.x < -8.5 || position.x > 9.5 || position.y < -3 || position.y > 12 || math.is_nan(position.y) {\n\t\tplayer_respawn(player)\n\t\treturn true\n\t}\n\tplayer_read_support(player)\n\treturn false\n}", "sourceLine": 86}, "bombs": {"source": "bomb_rain_before_step :: proc(game: ^Sandbox,dt: f32) {\n\tif game.applied.blast_mode!=.Falling_Bombs { return }\n\train:=&game.bomb_rain\n\tfor &bomb in rain.bombs { bomb.previous=from_b2(b2.Body_GetPosition(bomb.body)) }\n\train.until_drop-=dt\n\tif rain.until_drop<=0 {\n\t\tx:=rand.float32_range(-7,8,rand.default_random_generator(&rain.random))\n\t\tbomb_spawn(game,{x,BOMB_SKY_HEIGHT})\n\t\train.until_drop+=bomb_drop_delay(rain)\n\t}\n}", "sourceLine": 77}, "blast_query": {"source": "blast_connections :: proc(s: ^Scene,regions: []u64) -> [dynamic]u64 {\n\tset:=make(map[u64]bool); defer delete(set)\n\tfor id in regions { for connection in s.subdivisions[s.sub_rows[id]].incident_links { set[connection]=true } }\n\tresult: [dynamic]u64\n\tfor id in set { if s.connections[s.conn_rows[id]].live { append(&result,id) } }\n\tsort_ids(result[:])\n\treturn result\n}", "sourceLine": 31}, "destruction": {"source": "blast_load :: proc(distance,radius: f32) -> f32 {\n\tif radius <= 0 || distance >= radius { return 0 }\n\treturn BLAST_LOAD_MULTIPLIER*max(f32(0),radius-distance)\n}", "sourceLine": 281}, "physics": {"source": "physics_tick :: proc(s: ^Scene, dt: f32,calculate_loads: Load_Calculator = calculate_physics_loads) {\n\tassert(s.physics.active && dt > 0)\n\tphysics_sync_structure(s)\n\tb2.World_Step(s.physics.world,dt,PHYSICS_SUBSTEPS)\n\tphysics_read_motion(s)\n\tfailures := calculate_loads(s,dt)\n\tapply_failures(s,failures)\n\tdelete(failures.subdivisions); delete(failures.connections)\n\tdelete(failures.discard_subdivisions)\n\tphysics_sync_structure(s)\n}", "sourceLine": 306}, "model": {"source": "new_scene :: proc(minimum_width: f32) -> Scene {\n\treturn Scene{sub_rows=make(map[u64]int),conn_rows=make(map[u64]int),piece_rows=make(map[u64]int),connection_pairs=make(map[Endpoint_Pair]u64),minimum_width=minimum_width}\n}", "sourceLine": 149}, "geometry": {"source": "shared_segments :: proc(a,b: Polygon) -> [dynamic]Segment {\n\tresult: [dynamic]Segment\n\tfor i in 0..<len(a.points) {\n\t\tfor j in 0..<len(b.points) {\n\t\t\tif segment,ok := segment_overlap(Segment{a.points[i],a.points[(i+1)%len(a.points)]},Segment{b.points[j],b.points[(j+1)%len(b.points)]}); ok { append(&result,segment) }\n\t\t}\n\t}\n\treturn result\n}", "sourceLine": 40}, "state": {"source": "interpolate_pose :: proc(previous,current: Pose,alpha: f32) -> Pose {\n\tt := clamp(alpha,f32(0),f32(1))\n\tangle := current.angle-previous.angle\n\tfor angle > math.PI { angle -= 2*math.PI }\n\tfor angle < -math.PI { angle += 2*math.PI }\n\tresult := current\n\tresult.position=vadd(previous.position,vmul(vsub(current.position,previous.position),t))\n\tresult.angle=previous.angle+angle*t\n\treturn result\n}\n\n// Interpolate the shared frame, so rendered rigid cells stay rigid between ticks too.", "sourceLine": 198}, "render_cache": {"source": "stroke_style :: proc(width: f32,color: rl.Color) -> (f32,rl.Color) {\n if width<=0 { return 0,color }\n if width<1 { tint:=color; tint.a=u8(f32(color.a)*width); return 1,tint }\n return width,color\n}", "sourceLine": 238}, "debug_view": {"source": "screen_point :: proc(view: View,point: Vec2) -> rl.Vector2 { return {view.offset.x+point.x*view.scale,view.offset.y-point.y*view.scale} }", "sourceLine": 7}})) Object.assign(window.ATLAS.files[id], value);
